[JsonPropertyName("request-timeout-seconds")]
+public int RequestTimeoutSeconds { get; set; } = DefaultLocalTimeoutSeconds;

var timeout = provider.IsLocalModel
    ? ValidateTimeout(provider.RequestTimeoutSeconds)
    : DefaultCloudTimeout;

if (serviceType == AIServiceType.Ollama)
{
    using var handler = new HttpClientHandler();
    using var client = new HttpClient(handler) { Timeout = _config.RequestTimeout };
    kernelBuilder.AddOllamaChatCompletion(_config.Model, new Uri(endpoint), httpClient: client);
}

catch (OperationCanceledException ex) when (TimeoutClassifier.IsHttpTimeout(ex))
{
    throw new PasteActionException(
        ResourceLoaderInstance.ResourceLoader.GetString("PasteActionTimedOut"),
        ex,
        aiServiceMessage: FormatTimeoutLimit(providerConfig));
}
catch (OperationCanceledException)
{
    throw;
}
